-- Lot 204 : payloads 91 a 120 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-143","moteur":"chatgpt","payload":"[RaccourcIA — /datapipelinevisual]\n\nMISSION\nIllustrer le parcours des données de la source à l’usage. Sépare sources, transformations, stockage et destinations. N’invente ni outil ni intégration, indique les flux et les frontières des systèmes.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Pipeline de données » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Sépare sources, transformations, stockage et destinations. N’invente ni outil ni intégration, indique les flux et les frontières des systèmes. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"ec5c2de8ee8718be99b144868c3c07cf5134d28b0367c5b7c2448b479551758c"},{"ref":"RCI-IMG-143","moteur":"claude","payload":"[RaccourcIA — /datapipelinevisual]\n\nMISSION\nIllustrer le parcours des données de la source à l’usage. Sépare sources, transformations, stockage et destinations. N’invente ni outil ni intégration, indique les flux et les frontières des systèmes.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Pipeline de données » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Sépare sources, transformations, stockage et destinations. N’invente ni outil ni intégration, indique les flux et les frontières des systèmes. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"307fdc07d321a942e741035694500b06eb4f78f9cfc78ace735a92f66d39558c"},{"ref":"RCI-IMG-143","moteur":"gemini","payload":"[RaccourcIA — /datapipelinevisual]\n\nMISSION\nIllustrer le parcours des données de la source à l’usage. Sépare sources, transformations, stockage et destinations. N’invente ni outil ni intégration, indique les flux et les frontières des systèmes.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Pipeline de données » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Sépare sources, transformations, stockage et destinations. N’invente ni outil ni intégration, indique les flux et les frontières des systèmes. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni